	}
	if ($parts === ['reservations'] && $method === 'POST') {
		$user=currentUser(); $roomId=(int)($body['room_id']??0); $start=new DateTime((string)($body['start_time']??'')); $end=new DateTime((string)($body['end_time']??'')); if($end <= $start) fail('終了時刻は開始時刻より後にしてください');
		$maxDays=in_array($user['role'],['admin','developer'],true)?365:7; if($start > new DateTime("+$maxDays days")) fail("予約は{$maxDays}日先までです");
		$roomStmt=$pdo->prepare('SELECT * FROM rooms WHERE id=? FOR UPDATE'); $pdo->beginTransaction(); $roomStmt->execute([$roomId]); $room=$roomStmt->fetch(); if(!$room){$pdo->rollBack();fail('教室が見つかりません',404);} if((int)($room['is_disabled']??0)===1){$pdo->rollBack();fail('この教室は現在利用停止中です',409);}
		$weekday=(int)$start->format('N'); $date=$start->format('Y-m-d'); if($end->getTimestamp()-$start->getTimestamp()>14400){$pdo->rollBack();fail('予約は4時間以内にしてください');} if($room['is_closed_during_class_hours'] && $weekday<=5 && $start < new DateTime("$date 15:30:00") && $end > new DateTime("$date 08:30:00")){ $pdo->rollBack(); fail('平日の授業時間帯は予約できません'); }
