	if (($parts[0] ?? '') === 'reservations' && isset($parts[1]) && $method === 'DELETE') { $user=currentUser(); $id=(int)$parts[1]; $stmt=$pdo->prepare("UPDATE reservations SET status='cancelled' WHERE id=? AND status='active' AND (user_id=? OR ? IN ('teacher','admin','developer'))"); $stmt->execute([$id,$user['id'],$user['role']]); if(!$stmt->rowCount()) fail('予約を取り消せません',403); jsonResponse(['ok'=>true]); }
	if ($parts === ['reservations','auto-allocate'] && $method === 'POST') {
